import { creatures } from './data';

const Crumb=({children}:{children:React.ReactNode})=><div className="crumb"><a href="/">Chart room</a><span>›</span>{children}</div>;

const GuideHero=({src,alt,caption}:{src:string;alt:string;caption:string})=>{const base=src.replace(/\.png$/,'');return <figure className="guide-hero"><picture><source type="image/webp" srcSet={`${base}-768.webp 768w, ${base}-1280.webp 1280w`} sizes="(max-width: 820px) 100vw, 1080px"/><img src={src} width="1536" height="1024" alt={alt} decoding="async" loading="eager" fetchPriority="high"/></picture><figcaption><span>ORIGINAL GUIDE ART</span>{caption}</figcaption></figure>};

const Related=({links}:{links:[string,string][]})=><aside className="related"><p className="eyebrow">RELATED GUIDES</p><div>{links.map(([label,href])=><a href={href} key={href}>{label}<span>→</span></a>)}</div></aside>;

const locationStops=[
  {n:'01',name:'Lighthouse',marker:'Green marker',objective:'Finish the tutorial economy, prepare the Empty Beer Can, and clear Spider Crab.',summon:'Empty Beer Can → Spider Crab',handin:'Pick up the Spider Crab Shell, return it to the Lighthouse Keeper, and complete the hand-in for Boat Keys.',ready:'Boat Keys are in your inventory, the Radar is purchased, and the green destination marker is visible.',recover:'If the marker is absent, recover the Spider Crab Shell, complete the Lighthouse Keeper hand-in, and confirm the Radar is equipped before recasting.'},
  {n:'02',name:'Forest',marker:'Yellow marker',objective:'Complete the lake NPC’s Leech request, use the Modified Leech, and defeat Giant Piranha.',summon:'Three Leeches → Modified Leech → Giant Piranha',handin:'Return the Giant Piranha Skeleton to the quest NPC rather than treating it as ordinary loot.',ready:'The Forest hand-in is complete and the yellow route marker for Desert has appeared.',recover:'Check that you delivered all three Leeches first. If the boss is already down, search the landing area and inventory for the Skeleton before repeating the summon.'},
  {n:'03',name:'Desert',marker:'Red marker',objective:'Finish the Tourist’s endangered-creature request, receive the Carrot, and use it for Pufferfish.',summon:'Tourist request → Carrot → Pufferfish',handin:'Protect the Pufferfish Fin and return it to finish the local progression step.',ready:'The Fin exchange is acknowledged and the red route marker toward Rocks is available.',recover:'A normal lure cannot replace the Carrot. Reopen the Tourist dialogue and verify the request reward, then check your inventory for the Fin before starting over.'},
  {n:'04',name:'Rocks',marker:'Final coordinates',objective:'Catch Tuna with the Professional Boss Lure, place the Tuna on land, then survive the Albatross attack.',summon:'Professional Boss Lure → Tuna on land → Albatross',handin:'Take the Albatross Head back to the route NPC to receive the coordinates for Volcano.',ready:'The Albatross hand-in is complete and the final navigation clue is recorded before departure.',recover:'If Albatross does not engage, verify that the Tuna is the correct catch and is placed on open land. If the route stalls after the fight, recover the Head before leaving.'},
  {n:'05',name:'Volcano',marker:'Finale complete',objective:'Catch five native creatures, deliver them to the scientist, and receive the Fish Bucket.',summon:'Five native catches → scientist → Fish Bucket → Bowhead Whale body → crater → Mutated Bowhead Whale',handin:'Collect the Whale Fin after the mutated fight and return it to the scientist for the military boat key.',ready:'The scientist accepts the Whale Fin and the military boat key is secured.',recover:'If the Fish Bucket is missing, recheck all five native catches and the scientist hand-in. If the mutated fight will not start, confirm the Bowhead Whale body reached the crater. If the key is missing, recover the Whale Fin and return to the scientist.'},
];

export function LocationsGuide(){return <article className="article guide-article wide-guide"><Crumb>Locations</Crumb><p className="eyebrow">FIVE-LOCATION STORY ROUTE · CHECKED AUG 28, 2026</p><h1>How to Fish Game<br/><i>Locations &amp; Islands Route</i></h1><p className="standfirst">The main progression is a five-stop voyage: Lighthouse, Forest, Desert, Rocks, and Volcano. Every departure depends on a local objective, a named encounter, a protected quest item, and a confirmed hand-in. Use this route as a practical checklist, not simply a list of island names.</p>
<div className="trust"><b>CURRENT: PATCH 1.0.10</b><span>The August 27 patch keeps up to 64 dropped items persistent, addresses specific joining/loading and item-pickup failures, and fixes the respawn lock where dying after the Tuna setup could stop Albatross spawning. The earlier Patch 1.0.9 Easy/Hard difficulty note still applies.</span></div>
<GuideHero src="/images/guides/locations/five-location-route-hero.png" alt="Original low-poly ocean route with Lighthouse, Forest, Desert, Rocks and Volcano" caption="A visual course from the Lighthouse starting point to the Volcano finale. Developer Island is optional and is not a sixth story stop."/>
<nav className="quick-nav" aria-label="On this page"><b>ON THIS PAGE</b><a href="#route-map">Route map</a>{locationStops.map(stop=><a href={`#${stop.name.toLowerCase()}`} key={stop.name}>{stop.n} {stop.name}</a>)}<a href="#developer">Developer Island</a><a href="#troubleshoot-route">Troubleshooting</a></nav>
<section id="route-map"><h2>The route in one screen</h2><p>Think of each island as a locked dependency chain. Reaching land is not the same as unlocking the next destination, and defeating a boss is not the same as completing the island. The next marker appears only after the required item reaches the correct NPC. Before you sail, read the current objective, make a manual save, separate food from unique drops, and leave enough inventory room for the boss item.</p>
<div className="route-flow" role="img" aria-label="Five-step route from Lighthouse to Forest, Desert, Rocks and Volcano"><div><span>01</span><b>Lighthouse</b><small>Crab → Keys</small></div><i>→</i><div><span>02</span><b>Forest</b><small>Skeleton → Yellow</small></div><i>→</i><div><span>03</span><b>Desert</b><small>Fin → Red</small></div><i>→</i><div><span>04</span><b>Rocks</b><small>Head → Coordinates</small></div><i>→</i><div><span>05</span><b>Volcano</b><small>Whale finale</small></div></div>
<div className="callout"><b>The safest universal rule:</b> never eat, sell, cook, or leave behind a unique boss part until the related NPC has acknowledged it and the next marker or key is visible.</div></section>
{locationStops.map(stop=><section id={stop.name.toLowerCase()} className="route-stop" key={stop.name}><div className="route-stop-heading"><span>STOP {stop.n}</span><h2>{stop.name}</h2><b>{stop.marker}</b></div><div className="route-stop-grid"><div><h3>Objective</h3><p>{stop.objective}</p></div><div><h3>Summon / quest chain</h3><p>{stop.summon}</p></div><div><h3>Hand-in</h3><p>{stop.handin}</p></div><div><h3>Ready to leave when…</h3><p>{stop.ready}</p></div></div>{stop.name==='Volcano'&&<div className="checkpoint"><span>VOLCANO CHECKPOINT</span><b>Five native catches delivered → Fish Bucket received → Bowhead Whale body carried to crater → Mutated Bowhead Whale defeated → Whale Fin returned → military boat key awarded.</b></div>}<div className="recovery"><b>If progression stalls</b><p>{stop.recover}</p></div>{stop.name==='Lighthouse'&&<p>For camera-by-camera help with the opening economy, rod controls, boss setup, and departure, use the <a href="/locations/lighthouse">complete Lighthouse walkthrough</a>. For the fight itself, open the <a href="/bosses/spider-crab">Spider Crab combat guide</a>.</p>}{stop.name==='Rocks'&&<p>Use the <a href="/locations/rocks">complete Rocks Island walkthrough</a> for the Professional catch table, Tuna setup, Albatross cover cycle, and Volcano departure check.</p>}{stop.name==='Volcano'&&<p>Use the <a href="/locations/volcano">complete Volcano Island walkthrough</a> for the Scientific catch table, Scientist counter, Bowhead body carry, lava-safe final-boss loop, and military-boat ending.</p>}</section>)}
<section id="developer"><h2>Developer Island is optional</h2><p>Developer Island is a secret side destination, not part of the Lighthouse-to-Volcano story dependency. Do not count it as a required sixth island and do not detour there because a normal marker failed to appear. Finish the five-location route first, protect your main-save progression, and treat the secret area as post-route exploration. A missing Forest, Desert, Rocks, or Volcano marker is solved at the previous story hand-in—not at Developer Island.</p></section>
<section id="troubleshoot-route"><h2>Route troubleshooting before you repeat a boss</h2><div className="troubleshoot"><article><b>No colored marker</b><span>Return to the previous NPC. Confirm the unique drop was handed in, then check the new key, coordinates, and Radar state.</span></article><article><b>Quest item is missing</b><span>Search the fight area and your inventory before recasting. Patch 1.0.10 keeps up to 64 dropped items persistent, but a confirmed pickup is still safer than relying on the ground.</span></article><article><b>A joining player loads the wrong state</b><span>Update every player, reconnect, and compare the current objective and inventory. Patch 1.0.10 targets specific joining/loading and item-pickup failures.</span></article><article><b>Albatross will not respawn</b><span>Update the game and repeat the Tuna setup on open land. Patch 1.0.10 fixes the lock where dying after the Tuna setup could prevent Albatross spawning after respawn.</span></article><article><b>A boss is too punishing</b><span>Patch 1.0.9 introduced Easy and Hard settings. Lowering the difficulty changes creature health and damage, not the required quest chain.</span></article><article><b>Inventory is overloaded</b><span>Bank optional weapons, carry one recovery stack, and reserve space for the unique drop. Progression loot matters more than another ordinary catch.</span></article></div></section>
<Related links={[["Volcano Island 5 walkthrough","/locations/volcano"],["Rocks Island 4 walkthrough","/locations/rocks"],["Lighthouse first-island walkthrough","/locations/lighthouse"],["Beginner route and survival","/beginner-guide"],["Reel of Fortune cosmetics","/guides/reel-of-fortune"]]}/></article>}

const rocksCatches=creatures.filter(creature=>creature.island==='Rocks'&&creature.kind==='Creature');
const volcanoCatches=creatures.filter(creature=>creature.island==='Volcano'&&creature.kind==='Creature');
const RocksCapture=({src,alt,caption}:{src:string;alt:string;caption:string})=><figure className="rocks-capture"><img src={src} alt={alt} loading="lazy" decoding="async"/><figcaption><span>OWNER-PROVIDED GAMEPLAY</span>{caption}</figcaption></figure>;
const GameplayReconstruction=({src,alt,caption,eager=false}:{src:string;alt:string;caption:string;eager?:boolean})=>{const base=src.replace(/\.png$/,'');return <figure className="rocks-capture reconstruction-capture"><picture><source type="image/webp" srcSet={`${base}-768.webp 768w, ${base}-1280.webp 1280w`} sizes="(max-width: 820px) 100vw, 1080px"/><img src={src} width="1680" height="945" alt={alt} loading={eager?'eager':'lazy'} decoding="async" fetchPriority={eager?'high':'auto'}/></picture><figcaption><span>GAMEPLAY RECONSTRUCTION</span>{caption}</figcaption></figure>};

export function RocksGuide(){return <article className="article guide-article wide-guide rocks-guide"><Crumb><><a href="/locations">Locations</a><span>›</span>Rocks Island</></Crumb><p className="eyebrow">ISLAND 4 · PROFESSIONAL TIER · CHECKED AUG 28, 2026</p><h1>How to Fish Rocks Island<br/><i>Complete Walkthrough</i></h1><p className="standfirst">Rocks is the fourth stop on the five-location story route and the last preparation island before Volcano. Unlock it with the Pufferfish Fin hand-in, build cash with the Professional Lure pool, catch Tuna with the Professional Boss Lure, use the defeated Tuna to draw down Albatross, and return the Albatross Head for the final coordinates.</p>
<div className="trust"><b>CURRENT: PATCH 1.0.10</b><span>The current maintenance reference fixes the lock where dying after the Tuna setup could stop Albatross spawning after respawn. Prices and damage can change; this guide treats the route items, boss triggers, hand-in, and visible encyclopedia entries as the stable core.</span></div>
<RocksCapture src="/images/creatures/encyclopedia-professional.webp" alt="Owner-provided How to Fish encyclopedia capture showing Professional-tier Rocks creatures" caption="The Professional collection begins here. The visible in-game encyclopedia names and base values make this a field-identification image, not a stock illustration."/>
<nav className="quick-nav" aria-label="On this page"><b>ON THIS PAGE</b><a href="#rocks-route">Route at a glance</a><a href="#unlock-rocks">Unlock Rocks</a><a href="#professional-pool">10 catches</a><a href="#prepare">Preparation</a><a href="#tuna">Tuna</a><a href="#albatross">Albatross</a><a href="#volcano">Volcano unlock</a><a href="#rocks-trouble">Troubleshooting</a></nav>
<section id="rocks-route"><h2>Rocks Island route at a glance</h2><p>Rocks is a two-encounter dependency chain. The regular Professional Lure is for collection and money; the more expensive Professional Boss Lure is reserved for Tuna. Tuna is not the final objective and its body is not ordinary sale stock. Move the defeated Tuna onto open land near cover, let Albatross take the bait, defeat the bird, protect its Head, and finish the NPC hand-in before sailing away.</p><div className="route-flow rocks-flow" role="img" aria-label="Rocks Island route from Pufferfish Fin to Volcano coordinates"><div><span>01</span><b>Unlock Rocks</b><small>Pufferfish Fin hand-in</small></div><i>→</i><div><span>02</span><b>Prepare</b><small>Food, ranged gun, space</small></div><i>→</i><div><span>03</span><b>Catch Tuna</b><small>Professional Boss Lure</small></div><i>→</i><div><span>04</span><b>Draw the bird</b><small>Tuna body on land</small></div><i>→</i><div><span>05</span><b>Hand in Head</b><small>Volcano coordinates</small></div></div><div className="callout"><b>The run-ending mistake:</b> do not sell, cook, eat, lose, or abandon the defeated Tuna. It is the Albatross summon item. If it disappears, you must spend another Professional Boss Lure and repeat the Tuna fight.</div></section>
<section id="unlock-rocks"><h2>1. Unlock Rocks after the Desert boss hand-in</h2><p>Beating Pufferfish is only half of the Island 3 objective. Recover the <strong>Pufferfish Fin</strong>, return it to the Desert Tourist, and confirm the next route marker before boarding your boat. If Rocks does not appear, return to the Tourist and inspect the quest state instead of searching the ocean at random.</p><ol className="steps compact"><li><b>Finish the Tourist request.</b><span>Receive the Carrot, summon Pufferfish, and defeat it without losing the unique trophy.</span></li><li><b>Deliver the Pufferfish Fin.</b><span>The boss kill does not replace the NPC exchange. Keep the Fin separate from food and sale inventory.</span></li><li><b>Confirm the Rocks marker.</b><span>Open the Radar and verify the new destination is visible before spending fuel or leaving the Desert route.</span></li><li><b>Save on arrival.</b><span>Rocks contains two linked fights. A clean save before buying the boss lure gives you a safer recovery point.</span></li></ol></section>
<section id="professional-pool"><h2>2. Fill the ten-creature Professional Lure pool</h2><p>The owner-provided encyclopedia captures show ten regular Rocks entries tied to the Professional tier. Their displayed figures are reported <strong>base values</strong>: weight, Killscore, cooking, a rare Drip state, and balance updates can change the amount you actually receive. Use the table to identify a catch and compare relative value, not to promise an exact sale price.</p><div className="rocks-catch-table" role="list" aria-label="Rocks Professional Lure catches">{rocksCatches.map((creature,index)=><article role="listitem" key={creature.name}><span>{String(index+1).padStart(2,'0')}</span><b>{creature.name}</b><small>${creature.value.toLocaleString()} reported base</small></article>)}</div><RocksCapture src="/images/creatures/encyclopedia-scientific.webp" alt="Owner-provided How to Fish encyclopedia capture showing late Professional entries including Voxelfish, Parrotfish and Dripper" caption="Voxelfish, Parrotfish, and Dripper continue the Rocks pool on the next encyclopedia screen; the Scientific catches begin after them."/><p>For a focused money loop, land catches away from the water, finish the kill safely, and check the name and value before eating or selling. Dripper has the highest reported base value in this ten-entry set, while Bass is the lowest. A rare Drip appearance is a separate collection target; protect that body if you plan to use the <a href="/guides/reel-of-fortune">Reel of Fortune</a>.</p><div className="callout"><b>Visible cooking target: 1.50×.</b> The analyzed route removes a Red Snapper when the Grill reaches 1.50×, and the current cooking guide independently identifies 1.50× as the maximum. Watch the multiplier rather than a fixed number of seconds, remove the body as soon as it reaches the cap, and never test this with Tuna or another quest body.</div></section>
<section id="prepare"><h2>3. Prepare before buying the Professional Boss Lure</h2><p>Current independent walkthroughs report the Professional Boss Lure at <strong>$1,200</strong>. Check the shop label carefully: the ordinary Professional Lure fills the ten-creature pool, while the Boss version summons Tuna. Do not cast until food, ammunition, open inventory space, and the weapon you intend to use are ready.</p><div className="two-column"><div><h3>Minimum loadout</h3><ul><li>Professional Boss Lure for Tuna.</li><li>A dependable ranged firearm and spare ammunition.</li><li>Healing food that will not be confused with quest loot.</li><li>One open carry slot for important encounter items.</li><li>A clear strip of land for the Tuna body.</li></ul></div><div><h3>Useful upgrade</h3><ul><li>The asset library records the Sniper Rifle as a Rocks unlock.</li><li>Its community-reported shop price is $3,800; verify the current shop.</li><li>Long range is valuable against a flying target.</li><li>An upgraded automatic weapon is a valid alternative.</li><li>Do not spend so much that you cannot replace a failed boss lure.</li></ul></div></div><p>The old Patch 1.0.5 route visibly opens a bullet-upgrade box and the Suppressor attachment before the fight. That proves the preparation menu exists, but it does not establish a current 350/400 damage requirement. Buy enough controllable ranged damage and ammunition for repeated aerial passes; treat the Suppressor as optional unless your current shop description gives it a benefit you actually need.</p></section>
<section id="tuna"><h2>4. Catch Tuna and keep the body intact</h2><p>Equip the <strong>Professional Boss Lure</strong>, move to a landing area where the catch cannot slide back into the water, and put your weapon in an accessible slot before casting. Tuna becomes dangerous as soon as it reaches land. Strafe across its committed approach rather than backing up in a straight line, then attack during the recovery window. The orange bar is health; the thinner white bar below it is the encounter’s escape timer. If the white bar empties, the target leaves and the boss-lure step must be repeated.</p><div className="combat-grid"><article><span>CAST READY</span><b>Weapon before lure.</b><p>Place the firearm where you can switch immediately after the Tuna leaves the water.</p></article><article><span>SIDESTEP</span><b>Cross the attack line.</b><p>Move laterally when Tuna commits; do not let the jump herd you back toward the shoreline.</p></article><article><span>PUNISH</span><b>Shoot during recovery.</b><p>Use controlled bursts or close-range damage only after the attack has missed and the target is readable.</p></article><article><span>PROTECT</span><b>Keep the defeated Tuna.</b><p>Do not process the body. Carry or drag it to the Albatross setup area near solid cover.</p></article></div></section>
<section id="albatross"><h2>5. Use cover to beat Albatross</h2><GameplayReconstruction src="/images/guides/rocks/albatross-cover-guide.png" alt="Clean gameplay-style view from under the Rocks awning aiming a scoped rifle at Albatross" caption="Stand under the red shop or grill awning, track the bird through the open side, and expose yourself only for a controlled shot after its pass."/><RocksCapture src="/images/creatures/encyclopedia-bosses.webp" alt="Owner-provided How to Fish encyclopedia capture showing Tuna and Albatross among the special creatures" caption="Tuna and Albatross appear as separate encyclopedia entries because the Tuna catch becomes the trigger for the aerial boss."/><p>Place the defeated Tuna on open ground where the bird can reach it, but choose a position beside the red shop, grill awning, or another solid overhang. Albatross uses aerial swoops and damaging white falling projectiles. Move fully under the roof as a pass begins, wait for the attack to clear, then step out as the bird climbs, turns, or resets. Lead the target with a ranged weapon and return to cover before the next line-up.</p><div className="reel-flow rocks-combat-flow" role="img" aria-label="Albatross cover combat loop"><div><span>01</span><b>Bait in the open</b><small>Tuna body on land</small></div><i>→</i><div><span>02</span><b>Move to cover</b><small>Roof between you and bird</small></div><i>→</i><div><span>03</span><b>Let attack pass</b><small>No damage trade</small></div><i>→</i><div><span>04</span><b>Step out + lead</b><small>Shoot during reset</small></div></div><p>Albatross also has the white escape timer beneath its health. Do not hide indefinitely: take one safe shot during each reset so the encounter remains active. If you die after setting the Tuna, update the game before repeating the route—the current patch notes specifically address a respawn state that could prevent Albatross from spawning after death. In co-op, one player should call the bird’s direction while the other fires; stay close enough that neither player loses the Head drop area.</p></section>
<section id="volcano"><h2>6. Return the Albatross Head and verify Volcano</h2><p>Once Albatross is down, stop shooting and inspect the drops. The progression object is the <strong>Albatross Head</strong>, not an ordinary Meat Chunk. Pick the Head up before reorganizing food or sale loot, then return it to the Rocks route NPC tied to the scared-islanders objective. The success state is not merely a dead bird: the dialogue finishes and the coordinates for Volcano become available.</p><div className="checkpoint"><span>READY TO LEAVE ROCKS</span><b>Albatross defeated → Head secured → Head accepted by the route NPC → Volcano coordinates recorded → final destination visible before departure.</b></div><p>Make a save after the coordinate hand-in. Volcano begins the scientific catch tier and the whale finale, so arriving with a reliable ranged weapon, healing food, and clean inventory space is more useful than carrying every ordinary Rocks catch. Sell or bank surplus only after the Albatross Head exchange is confirmed, then continue with the <a href="/locations/volcano">complete Volcano Island 5 walkthrough</a>.</p></section>
<section id="rocks-trouble"><h2>Rocks troubleshooting</h2><div className="troubleshoot"><article><b>Rocks marker never appears</b><span>Return to the Desert Tourist and confirm the Pufferfish Fin was actually accepted. A boss kill without the trophy hand-in does not finish the unlock.</span></article><article><b>The cast catches normal fish</b><span>Check the item name. Professional Lure is the ordinary ten-creature pool; Professional Boss Lure is the Tuna trigger.</span></article><article><b>The white bar empties</b><span>That bar is the encounter escape timer. Stay engaged and make steady safe damage; health remaining does not matter if the timer reaches zero.</span></article><article><b>Tuna slides back into the sea</b><span>Choose a flatter landing lane, pull away from the shoreline, and fight from the inland side so the body remains usable.</span></article><article><b>Albatross does not spawn</b><span>Put the defeated Tuna on open land, move nearby, and update to the current patch. If the body was sold or cooked, catch another Tuna.</span></article><article><b>The bird keeps killing me</b><span>Stop fighting in the open. Put the red shop or grill roof between you and its swoop and falling projectiles, then fire only during the reset.</span></article><article><b>I picked up meat, not the Head</b><span>Search the drop area again. Meat Chunks are ordinary loot; only the Albatross Head completes the Volcano hand-in.</span></article><article><b>Volcano is still locked</b><span>Recover the Albatross Head and finish the NPC hand-in. Confirm the coordinates or destination marker before sailing away.</span></article></div></section>
<Related links={[["Volcano Island 5 walkthrough","/locations/volcano"],["Five-location route","/locations"],["All 49 creatures and values","/creatures"],["Lures and boss summons","/lures"],["Beginner five-island route","/beginner-guide"]]}/></article>}

export function VolcanoGuide(){return <article className="article guide-article wide-guide rocks-guide volcano-guide"><Crumb><><a href="/locations">Locations</a><span>›</span>Volcano Island</></Crumb><p className="eyebrow">ISLAND 5 · SCIENTIFIC TIER · CHECKED AUG 28, 2026</p><h1>How to Fish Volcano Island<br/><i>Complete Walkthrough</i></h1><p className="standfirst">Volcano is the fifth and final story location. Follow the coordinates earned from the Albatross Head, complete the Scientist’s fish request, use the Fish Bucket to defeat Bowhead Whale, carry the whole whale body to the crater, beat Mutated Bowhead Whale without stepping into lava, and return the Whale Fin for the military-boat key.</p>
<div className="trust"><b>CURRENT: PATCH 1.0.10</b><span>The route was cross-checked against current written walkthroughs and an older Patch 1.0.5 gameplay recording. The stable quest chain is published; old weapon damage, ammunition, and upgrade numbers are deliberately excluded.</span></div>
<GameplayReconstruction src="/images/guides/volcano/01-volcano-arrival.png" alt="Clean gameplay-style first-person arrival at Volcano with a fishing rod, Scientist, crates and lava ridge" caption="Land beside the Scientist and field shop. The black ground and orange lava make dropped bodies difficult to spot, so establish a clean working area before starting the final quest." eager/>
<nav className="quick-nav" aria-label="On this page"><b>ON THIS PAGE</b><a href="#volcano-route">Route at a glance</a><a href="#arrive-volcano">Arrival loadout</a><a href="#scientist-fish">Five-fish request</a><a href="#scientific-pool">Scientific catches</a><a href="#bowhead">Bowhead Whale</a><a href="#carry-crater">Carry to crater</a><a href="#mutated-whale">Final boss</a><a href="#whale-fin">Whale Fin ending</a><a href="#goblin-shark">Optional boss</a><a href="#volcano-trouble">Troubleshooting</a></nav>
<section id="volcano-route"><h2>Volcano route at a glance</h2><p>The finale has two separate fishing steps and two linked whale fights. The regular <strong>Scientific Lure</strong> is used to satisfy the Scientist and build the five-creature collection pool. The quest reward, <strong>Fish Bucket</strong>, is then used for Bowhead Whale. The defeated whale is not the final reward—it becomes the physical summon for Mutated Bowhead Whale when carried to the crater. The final Whale Fin must still reach the Scientist before the story exit is unlocked.</p><div className="route-flow volcano-flow" role="img" aria-label="Volcano route from Scientist request to military boat key"><div><span>01</span><b>Meet Scientist</b><small>Prepare + buy Scientific Lure</small></div><i>→</i><div><span>02</span><b>Deliver five</b><small>Receive Fish Bucket</small></div><i>→</i><div><span>03</span><b>Beat Bowhead</b><small>Keep whole body</small></div><i>→</i><div><span>04</span><b>Use crater</b><small>Mutated Whale</small></div><i>→</i><div><span>05</span><b>Return Whale Fin</b><small>Military-boat key</small></div></div><div className="callout"><b>Do not process either progression body.</b> The first Bowhead Whale body must reach the crater intact, and the Whale Fin from the mutated fight must reach the Scientist. Selling, cooking, eating, or abandoning either one breaks the current step.</div></section>
<section id="arrive-volcano"><h2>1. Arrive with a ranged weapon, healing, and empty space</h2><p>Volcano is not a good place to discover that your inventory is full. Before leaving Rocks, finish the Albatross Head exchange, save the new coordinates, bank extra ordinary catches, and reserve room for Scientific fish, the Fish Bucket, the Bowhead body interaction, and the Whale Fin. Bring a reliable ranged gun you already understand rather than spending every dollar on an unfamiliar weapon after landing.</p><div className="two-column"><div><h3>Minimum story loadout</h3><ul><li>Radar or recorded Volcano coordinates from Rocks.</li><li>One dependable ranged weapon with adequate ammunition.</li><li>Healing food in a clearly separated slot.</li><li>Scientific Lure money and several free inventory spaces.</li><li>A clean save made after the Albatross Head hand-in.</li></ul></div><div><h3>Useful but not mandatory</h3><ul><li>Assault Rifle for consistent moving-target damage.</li><li>Magazine and recoil upgrades you can afford.</li><li>Extra food for two consecutive whale fights.</li><li>A co-op caller who watches jumps and lava lanes.</li><li>Storage space for optional Scientific collection catches.</li></ul></div></div><p>The analyzed older route uses an Assault Rifle and high bullet upgrades, but no specific damage target is required here because difficulty and balance patches change the math. The practical test is whether you can keep moving while placing controlled shots. If your current ranged gun can do that and you have enough ammunition for two boss health bars, it is a valid story weapon.</p></section>
<section id="scientist-fish"><h2>2. Buy the $500 Scientific Lure and fill the Scientist’s counter</h2><p>Find the yellow-suited Scientist beside the shore shop. Current independent guidance and the analyzed shop frame both place the regular <strong>Scientific Lure at $500</strong>. Buy the ordinary version first. Do not accidentally buy or equip the Scientific Boss Lure: that one belongs to the optional Goblin Shark collection branch and does not replace the Scientist’s quest loop.</p><p>There is a small source disagreement worth handling honestly. One current walkthrough reports that the Scientist’s counter accepts any five fish, while another describes five native Volcano catches. The safest route is to land <strong>five fresh creatures with the Scientific Lure at Volcano</strong>. This satisfies the stricter interpretation, fills the final regular collection tier, and avoids arriving with old bodies that fail to increment the objective. After each hand-in, check the Scientist’s counter or dialogue before catching the next one.</p><ol className="steps compact"><li><b>Start the Scientist dialogue.</b><span>Activate the quest before assuming carried fish will count.</span></li><li><b>Equip the regular Scientific Lure.</b><span>Read the full item name; the Boss version is for Goblin Shark.</span></li><li><b>Catch and secure one creature at a time.</b><span>Kill it away from lava and water, then confirm the pickup.</span></li><li><b>Deliver and watch the counter.</b><span>If a body does not increment the quest, switch to a fresh Scientific catch.</span></li><li><b>Collect the Fish Bucket.</b><span>Do not leave the NPC until the special Bowhead summon is visible in inventory.</span></li></ol><div className="checkpoint"><span>SCIENTIST CHECKPOINT</span><b>The five-fish step is complete only when the Scientist acknowledges it and the Fish Bucket appears. Five bodies on the ground or in your inventory are not the success state.</b></div></section>
<section id="scientific-pool"><h2>3. Identify the five regular Scientific creatures</h2><p>The owner-provided encyclopedia records five regular Volcano entries in the Scientific tier. Values below are reported base values from that capture, not guaranteed final sale prices. Weight, cooking, Killscore, a rare Drip state, and patches can change the actual amount. For the story quest, the important signal is whether the Scientist’s counter advances—not which of these names has the highest base value.</p><div className="rocks-catch-table volcano-catch-table" role="list" aria-label="Volcano Scientific Lure catches">{volcanoCatches.map((creature,index)=><article role="listitem" key={creature.name}><span>{String(index+1).padStart(2,'0')}</span><b>{creature.name}</b><small>${creature.value.toLocaleString()} reported base</small></article>)}</div><RocksCapture src="/images/creatures/encyclopedia-scientific.webp" alt="Owner-provided How to Fish encyclopedia showing Blobfish, Oarfish, Anglerfish, Stonefish and Superdwarf Fish" caption="The final regular collection tier contains Blobfish, Oarfish, Anglerfish, Stonefish, and Superdwarf Fish. Use fresh Scientific catches for the safest Scientist hand-in."/><p>Superdwarf Fish has the highest reported base value in this five-entry set; Blobfish is the lowest. If you continue fishing for money after the quest, keep ordinary sale bodies well away from the Bowhead staging area so you cannot grab the wrong object during the finale. Current money guidance also reports that Volcano lava can apply the maximum 1.50× cooking bonus immediately without a burn timer, but treat the lava edge as a deliberate economy tool only after the story bodies are safe. Never test it with Bowhead Whale or Whale Fin.</p></section>
<section id="bowhead"><h2>4. Use Fish Bucket and run when Bowhead Whale jumps</h2><p>With the Fish Bucket in inventory, choose a broad flat lane away from the water and lava. Put your ranged gun in the next accessible slot, heal before casting, and leave a clear path inland. Bowhead Whale is enormous and can hide your view when it closes distance. Its most readable danger cue is becoming airborne: when the body rises, stop firing and sprint laterally or away from the landing line. Resume shooting only after the body slam finishes and the whale’s direction is readable again.</p><div className="combat-grid"><article><span>SUMMON</span><b>Use Fish Bucket.</b><p>Confirm the Scientist reward, then cast from a landing lane that keeps the body on usable ground.</p></article><article><span>READ</span><b>Watch the whole silhouette.</b><p>The camera can fill with the whale. Track whether it is grounded, charging, or lifting for a slam.</p></article><article><span>RUN</span><b>Break away on the jump.</b><p>Do not trade damage under an airborne whale. Sprint out of the landing line and preserve health.</p></article><article><span>PUNISH</span><b>Fire after landing.</b><p>Use the recovery after a missed charge or body slam for controlled shots, then rebuild distance.</p></article></div><p>Do not let the fight drag you into the ocean or across a lava seam. A safe circle on plain black ground is better than chasing the boss for one extra burst. In co-op, one player calls the jump while both move in the same direction; splitting across the whale can make it turn unpredictably and land on the recovering player.</p></section>
<section id="carry-crater"><h2>5. Keep the whole Bowhead body and carry it to the crater</h2><GameplayReconstruction src="/images/guides/volcano/02-bowhead-to-crater.png" alt="Clean gameplay-style first-person view carrying the whole Bowhead Whale body toward Volcano lava crater" caption="The first whale is a progression object. Lift the whole body, follow solid black ground to the crater, and keep it away from sale, food, and lava-cooking piles."/><p>When Bowhead Whale dies, stop firing and secure the <strong>whole body</strong>. Do not carve it into meat, cook it, sell it, or leave it beside ordinary fish. Before beginning the carry, reload, heal, and confirm you still have ammunition for the stronger mutated fight. Once the body reaches the crater trigger and the transformation begins, your preparation window is effectively over.</p><ol className="steps"><li><b>Clear the route first.</b><span>Walk the path without the body and identify continuous black ground around every lava seam.</span></li><li><b>Heal and reload.</b><span>The mutated fight begins after the crater step; prepare before placing the body.</span></li><li><b>Carry the whole body.</b><span>Keep the large whale centered and move slowly enough to avoid dropping it into an unreachable edge.</span></li><li><b>Approach from the safe side.</b><span>Use the wooden or black-rock route rather than jumping across glowing lava.</span></li><li><b>Place or throw it into the crater trigger.</b><span>Back away as soon as the transformation state is accepted and draw your ranged weapon.</span></li></ol><div className="callout"><b>Do not stand on the lava.</b> The old walkthrough explicitly warns against stepping into it during this carry and fight. Even if ordinary fish can use lava for an instant cooking multiplier, the player and unique quest objects should stay on the solid route.</div></section>
<section id="mutated-whale"><h2>6. Beat Mutated Bowhead Whale by moving first</h2><GameplayReconstruction src="/images/guides/volcano/03-mutated-bowhead-fight.png" alt="Clean gameplay-style first-person fight against airborne Mutated Bowhead Whale between Volcano lava lanes" caption="When the mutated whale lifts, sprint along solid ground. Turn and fire only after the leap, charge, or body slam has committed past your lane."/><p>Mutated Bowhead Whale repeats the large-body pressure of the first fight but adds a more aggressive pace and a lava-filled arena. Current walkthroughs describe charges, body slams, and lava pressure; the analyzed route visibly demonstrates repeated airborne attacks and warns the player away from glowing pools. Survival comes before damage. Keep a broad lane, watch the whale rather than the crosshair, and move before an attack reaches you.</p><div className="reel-flow volcano-combat-flow" role="img" aria-label="Mutated Bowhead Whale combat loop"><div><span>01</span><b>Choose solid lane</b><small>No lava behind you</small></div><i>→</i><div><span>02</span><b>Watch the lift</b><small>Stop firing</small></div><i>→</i><div><span>03</span><b>Sprint across line</b><small>Let attack pass</small></div><i>→</i><div><span>04</span><b>Turn + controlled burst</b><small>Use recovery window</small></div></div><p>Do not backpedal while staring through a scope. That is how players step into lava. Keep the weapon at a wider view during movement, then aim only after the whale lands or passes. If the boss throws or scatters lava into your previous lane, rotate around the outside instead of squeezing through a glowing gap. A smaller guaranteed shooting window is better than dying with half a magazine unused.</p><p>The white bar beneath the health display is the encounter’s escape timer. You still need steady damage, but hiding or running so far that the fight disengages can waste the entire chain. The correct rhythm is one safe attack window per boss pass: move, confirm the miss, fire, reload while repositioning, and repeat.</p></section>
<section id="whale-fin"><h2>7. Protect the Whale Fin and unlock the military boat</h2><p>After the mutated whale falls, stop shooting and search the immediate landing area for the <strong>Whale Fin</strong>. This is the final protected quest drop. Pick it up before food, meat, or optional sale loot, then return to the yellow-suited Scientist. The finale is complete only when the Scientist accepts the Fin and awards the key for the RHIB or military boat used to leave for the mainland ending.</p><div className="checkpoint"><span>VOLCANO COMPLETE</span><b>Mutated Bowhead Whale defeated → Whale Fin picked up → Fin accepted by Scientist → military-boat key received → RHIB available for the ending route.</b></div><p>Save after the Scientist hand-in and verify the key in inventory before boarding. Developer Island and other optional discoveries are not required to make Volcano count as the fifth story location. If a new coordinate or side route appears after the finale, treat it as postgame exploration; do not postpone the Whale Fin exchange or risk carrying the unique drop across the ocean.</p></section>
<section id="goblin-shark"><h2>Optional: Scientific Boss Lure and Goblin Shark</h2><p>Goblin Shark belongs to the Volcano collection tier but is separate from the main Bowhead finale. Current lure references pair it with the <strong>Scientific Boss Lure</strong>. The Scientist’s five-fish request, Fish Bucket, regular Bowhead body, Mutated Bowhead Whale, and Whale Fin are the story dependency; Goblin Shark is an optional completion branch.</p><p>Finish the story first unless you have enough money, ammunition, and recovery to risk another special cast. This page does not invent a current lure price or boss damage pattern because the analyzed segment does not cleanly establish that encounter. When you attempt it, use the same safe special-cast routine: verify the full lure name, clear a landing lane, heal, equip the ranged gun, leave inventory space, and preserve any unique drop until you understand its purpose.</p></section>
<section id="volcano-trouble"><h2>Volcano troubleshooting</h2><div className="troubleshoot"><article><b>Volcano is not on Radar</b><span>Return to Rocks. Confirm the Albatross Head—not Meat Chunks—was accepted and that the Volcano coordinates were recorded.</span></article><article><b>The Scientist counter does not move</b><span>Start the dialogue, then deliver one fresh Volcano catch made with the regular Scientific Lure. If that works, repeat until five.</span></article><article><b>I caught Goblin Shark instead</b><span>You used Scientific Boss Lure. Switch to the regular $500 Scientific Lure for the Scientist and collection pool.</span></article><article><b>Fish Bucket is missing</b><span>Reopen the Scientist dialogue and check the quest counter. Five catches are not enough until the NPC hand-in awards the special item.</span></article><article><b>Bowhead body disappeared</b><span>Search the landing lane and persistent dropped items before recasting. If it was sold, cooked, lost to water, or processed, repeat the Fish Bucket step from a safer lane.</span></article><article><b>Mutated Whale will not spawn</b><span>Bring the whole regular Bowhead body to the actual crater trigger. Meat, a partial drop, or an ordinary whale-related item does not substitute.</span></article><article><b>I keep dying in lava</b><span>Stop aiming while retreating. Choose a solid black lane first, sprint when the whale lifts, and turn to fire only after the attack passes.</span></article><article><b>The white bar empties</b><span>That is the escape timer. Stay within the arena and land one controlled burst after each safe dodge instead of hiding indefinitely.</span></article><article><b>Whale Fin is missing</b><span>Search the final landing area before leaving or moving ordinary loot. Update and reload the latest safe state only after checking the ground and inventory.</span></article><article><b>Military boat is still locked</b><span>The final boss kill is not enough. Carry the Whale Fin back to the Scientist and verify the RHIB key before trying the boat.</span></article></div></section>
<Related links={[["Rocks Island 4 walkthrough","/locations/rocks"],["Five-location story route","/locations"],["All 49 creatures and values","/creatures"],["Boss and special encounters","/bosses"],["Lures and bait guide","/lures"]]}/></article>}

export function ReelOfFortuneGuide(){return <article className="article guide-article"><Crumb><><a href="/beginner-guide">Guides</a><span>›</span>Reel of Fortune</></Crumb><p className="eyebrow">DRIP CREATURES · COSMETIC SKINS · CHECKED AUG 28, 2026</p><h1>How to Use the<br/><i>Reel of Fortune</i></h1><p className="standfirst">Catch a rare Drip creature, kill it, and carry the Drip body to the Reel of Fortune for one random cosmetic equipment or weapon skin. The reward changes appearance only. Read the result, hold the matching item, and cycle its unlocked looks with Z or C.</p>
<div className="trust"><b>CURRENT: PATCH 1.0.10</b><span>The August 27 update addresses specific joining/loading and item-pickup failures. It does not publish skin odds, a pity system, shared co-op ownership, or guest-save behavior.</span></div>
<GuideHero src="/images/guides/reel-of-fortune/reel-machine-hero.png" alt="Original low-poly co-op players offering a rare iridescent creature to a neon prize reel near a lighthouse" caption="One rare Drip creature is the input; a random visual skin is the output. No stats, damage, or attachments are added."/>
<nav className="quick-nav" aria-label="On this page"><b>ON THIS PAGE</b><a href="#quick-answer">Quick answer</a><a href="#find-drip">Find a Drip</a><a href="#use-reel">Use the machine</a><a href="#equip">Equip the skin</a><a href="#gold">GOLD GOLD GOLD</a><a href="#reel-trouble">Troubleshooting</a></nav>
<section id="quick-answer"><h2>Quick answer: Drip body in, cosmetic skin out</h2><p>Keep fishing the normal creature loop until you find a rare <strong>Drip creature</strong>. Catch it, kill it, and carry the dead Drip body to the Reel of Fortune. The result is random and belongs to a particular supported item. It may be a weapon or another piece of equipment. Remember the item named by the result, equip or hold that item, then press <strong>Z</strong> or <strong>C</strong> to move through the available appearances.</p>
<div className="reel-flow" role="img" aria-label="Four-step Reel of Fortune process"><div><span>01</span><b>Catch + kill</b><small>Keep the Drip body</small></div><i>→</i><div><span>02</span><b>Use the Reel</b><small>Carry the body in</small></div><i>→</i><div><span>03</span><b>Read the item</b><small>Random skin result</small></div><i>→</i><div><span>04</span><b>Hold + Z / C</b><small>Cycle appearance</small></div></div>
<div className="callout"><b>Cosmetic means cosmetic:</b> a skin does not increase damage, attack speed, magazine size, recoil control, fishing performance, sale value, or any other stat. Buy upgrades and attachments for performance; use the Reel for appearance.</div></section>
<section id="find-drip"><h2>1. Catch, kill, and protect a Drip body</h2><p>A Drip is a rare creature variant, not a named boss summon. Current written guides establish the repeatable action: fish normally, notice the rare visual treatment, land the catch, kill it, and preserve the body for the machine. Do not cook, sell, or use the body as recovery food if your goal is a skin.</p><ol className="steps"><li><b>Choose a safe ordinary fishing loop.</b><span>Use a route where you can land catches away from deep water and reach storage or the machine without taking a boss detour.</span></li><li><b>Confirm the rare Drip variant.</b><span>Inspect the catch before spending time carrying an ordinary creature with a similar shape.</span></li><li><b>Kill the catch and keep its body.</b><span>The verified input is the dead Drip body. Secure it on land before reorganizing your inventory.</span></li><li><b>Make inventory room.</b><span>Drop or bank low-value clutter first. Patch 1.0.10 addresses item-pickup failures, but carrying the intended input is safer than leaving it on the shore.</span></li></ol><p>There is no need to invent a special Drip-only lure for this guide. If one does not appear, continue the normal catch loop. The site deliberately does not publish an encounter percentage or a guaranteed number of catches because no official odds are cited here.</p></section>
<section id="use-reel"><h2>2. Use the Reel without losing track of the reward</h2><p>Approach the Reel carrying the dead Drip body. Use it when the machine accepts the body, let the result resolve, and focus on the equipment name. The skin is not a stronger weapon waiting on the floor; it is an appearance associated with an item. If you rush away without reading the result, you may later search the wrong weapon.</p><ol className="steps compact"><li><b>Confirm the verified input.</b><span>This guide verifies one dead Drip body. Other possible inputs are outside this guide’s verified scope and are not needed for the cosmetic route described here.</span></li><li><b>Start the result.</b><span>Allow the visual sequence to finish before changing items or walking away.</span></li><li><b>Read the matching item.</b><span>Remember or note which weapon or equipment category received the appearance.</span></li><li><b>Check that item immediately.</b><span>Hold it and test Z and C while the result is still fresh.</span></li></ol><div className="checkpoint"><span>SUCCESS CHECK</span><b>You have completed the loop when the matching item visibly cycles to a new appearance. Do not judge success by damage numbers—the reward is not a stat upgrade.</b></div></section>
<section id="equip"><h2>3. Equip and cycle the skin with Z or C</h2><p>Skins are checked on the item they belong to. Put the relevant weapon, rod, or equipment in your hands, then press <strong>Z</strong> or <strong>C</strong>. The keys move through that item’s available appearances in opposite directions. If nothing changes, first confirm that you are holding the exact item named by the Reel result rather than a similar weapon.</p><div className="two-column"><div><h3>Correct sequence</h3><ul><li>Identify the reward item.</li><li>Own and hold that exact item.</li><li>Press Z once and inspect the model.</li><li>Press C to cycle the other direction.</li><li>Compare appearance, not combat stats.</li></ul></div><div><h3>What the skin does not do</h3><ul><li>It does not add an attachment.</li><li>It does not upgrade weapon damage.</li><li>It does not improve the fishing rod.</li><li>It does not create a second physical item.</li><li>It does not prove another player owns it.</li></ul></div></div><p>Control bindings can change with platform or custom settings. Z and C are the verified keyboard guidance used here; if those inputs do not respond, inspect the current control settings instead of repeatedly spending Drips.</p></section>
<section id="gold"><h2>4. What GOLD GOLD GOLD means</h2><p>The achievement list connects <strong>GOLD GOLD GOLD</strong> with a legendary Reel result. A regular skin still completes the cosmetic loop, but the achievement depends on the legendary outcome. This page does not publish a legendary percentage, a pity counter, or a maximum number of attempts: those claims need an official or directly measurable source, and none is asserted here.</p><p>Treat the achievement as optional cleanup rather than a progression gate. Finish the five-location story, establish a safe catch-and-storage loop, and spend Drips only when losing that creature will not interrupt another goal. A legendary appearance still remains visual; its rarity does not turn it into a performance upgrade.</p></section>
<section id="reel-trouble"><h2>Troubleshooting the Reel and missing skins</h2><div className="troubleshoot"><article><b>The machine will not start</b><span>Confirm the catch is the rare Drip variant and that it is dead. Carry the Drip body to the interaction point and try again.</span></article><article><b>I cannot find the reward</b><span>Hold the exact item named by the result and press Z or C. The reward is an unlocked appearance, not necessarily a pickup on the ground.</span></article><article><b>Z and C do nothing</b><span>Check that you own and hold the matching item, then review the current keyboard bindings. Do not spend another Drip until you test the correct category.</span></article><article><b>The display or item state looks wrong</b><span>Update to Patch 1.0.10, return to the main menu safely, reload, and inspect the item again. The patch addresses specific joining/loading and item-pickup failures.</span></article><article><b>Co-op players see different results</b><span>Do not assume shared skin ownership or guest-save behavior. Each player should verify the item in their own inventory and save state.</span></article><article><b>I expected roulette behavior</b><span>Use these instructions only for the verified dead-Drip-body cosmetic route. This page does not claim that Reel of Fortune and roulette are equivalent systems.</span></article></div></section>
<Related links={[["Five-location route","/locations"],["All 28 achievements","/achievements"],["Creature checklist","/creatures"]]}/></article>}
